SET NOCOUNT ON; SET LOCK_TIMEOUT 60000;
SELECT N'_AccumRg3305' table_name,
COUNT_BIG(j.[_RecorderRRef]) june_rows,
COUNT_BIG(s.[_RecorderRRef]) september_rows,
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL THEN 1 ELSE 0 END)) [retained],
SUM(CONVERT(bigint,CASE WHEN s.[_RecorderRRef] IS NULL THEN 1 ELSE 0 END)) [removed],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NULL THEN 1 ELSE 0 END)) [added],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Period])<>CONVERT(varbinary(max),s.[_Period]) OR (j.[_Period] IS NULL AND s.[_Period] IS NOT NULL) OR (j.[_Period] IS NOT NULL AND s.[_Period] IS NULL)) THEN 1 ELSE 0 END)) [changed_Period],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Active])<>CONVERT(varbinary(max),s.[_Active]) OR (j.[_Active] IS NULL AND s.[_Active] IS NOT NULL) OR (j.[_Active] IS NOT NULL AND s.[_Active] IS NULL)) THEN 1 ELSE 0 END)) [changed_Active],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_RecordKind])<>CONVERT(varbinary(max),s.[_RecordKind]) OR (j.[_RecordKind] IS NULL AND s.[_RecordKind] IS NOT NULL) OR (j.[_RecordKind] IS NOT NULL AND s.[_RecordKind] IS NULL)) THEN 1 ELSE 0 END)) [changed_RecordKind],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld3307_RRRef])<>CONVERT(varbinary(max),s.[_Fld3307_RRRef]) OR (j.[_Fld3307_RRRef] IS NULL AND s.[_Fld3307_RRRef] IS NOT NULL) OR (j.[_Fld3307_RRRef] IS NOT NULL AND s.[_Fld3307_RRRef] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld3307_RRRef],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld3308_RRRef])<>CONVERT(varbinary(max),s.[_Fld3308_RRRef]) OR (j.[_Fld3308_RRRef] IS NULL AND s.[_Fld3308_RRRef] IS NOT NULL) OR (j.[_Fld3308_RRRef] IS NOT NULL AND s.[_Fld3308_RRRef] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld3308_RRRef],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld3311])<>CONVERT(varbinary(max),s.[_Fld3311]) OR (j.[_Fld3311] IS NULL AND s.[_Fld3311] IS NOT NULL) OR (j.[_Fld3311] IS NOT NULL AND s.[_Fld3311] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld3311],
SUM(CONVERT(bigint,CASE WHEN j.[_RecorderRRef] IS NOT NULL AND s.[_RecorderRRef] IS NOT NULL AND (CONVERT(varbinary(max),j.[_Fld3312])<>CONVERT(varbinary(max),s.[_Fld3312]) OR (j.[_Fld3312] IS NULL AND s.[_Fld3312] IS NOT NULL) OR (j.[_Fld3312] IS NOT NULL AND s.[_Fld3312] IS NULL)) THEN 1 ELSE 0 END)) [changed_Fld3312] FROM [FitnessRestored_20260630_original].dbo.[_AccumRg3305] j FULL JOIN [FitnessRestored_20260630_macos].dbo.[_AccumRg3305] s ON j.[_RecorderRRef]=s.[_RecorderRRef] AND j.[_RecorderTRef]=s.[_RecorderTRef] AND j.[_LineNo]=s.[_LineNo] AND j.[_Fld346]=s.[_Fld346] FOR JSON PATH, INCLUDE_NULL_VALUES;
